mapper.select:
/* StockMapper.selectStockList : Stock List 조회 */
SELECT st.TR_CODE , (SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = st.ENT_CODE AND CODE = st.TR_CODE AND GROUP_CODE = 'ECM_DELIVERY_CODE') AS TR_NAME , st.BOUND , st.BOUND_TYPE , st.AGENT_CODE , (SELECT CASE WHEN st.AGENT_CODE = #{srchEntCode} THEN #{srchEntCode} ELSE CUSTOMER_NAME END FROM TB_SMS_CUSTOMER WHERE ENT_CODE = st.ENT_CODE AND CUSTOMER_CODE = st.AGENT_CODE) AS CUSTOMER_NAME
, CASE WHEN ISNULL(cus.CUSTOMER_LEVEL, 1) = 1 THEN st.AGENT_CODE ELSE cus.PARENT_CUSTOMER_CODE END PARENT_AGENT_CODE , (SELECT CASE WHEN st.AGENT_CODE = #{srchEntCode} THEN #{srchEntCode} ELSE CUSTOMER_NAME END FROM TB_SMS_CUSTOMER WHERE ENT_CODE = st.ENT_CODE AND CUSTOMER_CODE = (CASE WHEN ISNULL(cus.CUSTOMER_LEVEL, 1) = 1 THEN st.AGENT_CODE ELSE cus.PARENT_CUSTOMER_CODE END)) AS PARENT_CUSTOMER_NAME
, st.SEQ_NO , st.ENT_CODE , st.ENT_BUSINESS_CODE , st.STOCK_DATE , st.RE_STOCK_DATE , st.START_NO , st.END_NO , st.CURRENT_NO , st.STOCK_TYPE , st.STOCK_METHOD , st.STOCK_USE_YN , st.REGISTER_USER_ID , (SELECT USER_LOGIN_ID FROM TB_SMS_USER WHERE ENT_CODE = st.ENT_CODE AND USER_ID = st.REGISTER_USER_ID) AS USER_LOGIN_ID , (SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = st.ENT_CODE AND USER_ID = st.REGISTER_USER_ID) AS USER_NAME , CONVERT(VARCHAR,st.REGISTER_DATE_TIME,23) AS REGISTER_DATE_TIME , st.UPDATE_USER_ID , CONVERT(VARCHAR,st.UPDATE_DATE_TIME,23) AS UPDATE_DATE_TIME
, (CASE WHEN st.TR_CODE IN('KOREX','KOREXMUL','HANJIN','JP-AIR','JP-SEA','LOTTE') THEN (CASE WHEN ISNULL(st.CURRENT_NO, 0) = 0 THEN 0 ELSE CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.CURRENT_NO),1,11)) - CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.START_NO),1,11)) + 1 END) WHEN st.TR_CODE IN ('EMS-KP','EMS-TS') THEN (CASE WHEN ISNULL(st.CURRENT_NO, 0) = 0 THEN 0 ELSE CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.CURRENT_NO),1,8)) - CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.START_NO),1,8)) + 1 END) ELSE (CASE WHEN ISNULL(st.CURRENT_NO, 0) = 0 THEN 0 ELSE st.CURRENT_NO - st.START_NO + 1 END) END ) AS USED_COUNT
, (CASE WHEN st.TR_CODE IN('KOREX','KOREXMUL','HANJIN','JP-AIR','JP-SEA','LOTTE') THEN (CASE WHEN ISNULL(st.CURRENT_NO, 0) = 0 THEN CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.END_NO),1,11)) - CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.START_NO),1,11)) + 1 ELSE CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.END_NO),1,11)) - CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.CURRENT_NO),1,11)) END) WHEN st.TR_CODE IN ('EMS-KP','EMS-TS') THEN (CASE WHEN ISNULL(st.CURRENT_NO, 0) = 0 THEN CONVERT(DECIMAL(9),SUBSTRING(CONVERT(VARCHAR(18),st.END_NO),1,8)) - CONVERT(DECIMAL(9),SUBSTRING(CONVERT(VARCHAR(18),st.START_NO),1,8)) + 1 ELSE CONVERT(DECIMAL(9),SUBSTRING(CONVERT(VARCHAR(18),st.END_NO),1,8)) - CONVERT(DECIMAL(9),SUBSTRING(CONVERT(VARCHAR(18),st.CURRENT_NO),1,8)) END) ELSE (CASE WHEN ISNULL(st.CURRENT_NO, 0) = 0 THEN st.END_NO - st.START_NO + 1 ELSE st.END_NO - st.CURRENT_NO END) END ) AS UNUSED_COUNT
, (CASE WHEN st.TR_CODE IN('KOREX','KOREXMUL','HANJIN','JP-AIR','JP-SEA','LOTTE') THEN (CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.END_NO),1,11)) - CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.START_NO),1,11)) + 1) WHEN st.TR_CODE IN ('EMS-KP', 'EMS-TS') THEN (CONVERT(DECIMAL(9),SUBSTRING(CONVERT(VARCHAR(18),st.END_NO),1,8)) - CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.START_NO),1,8)) + 1) ELSE (st.END_NO - st.START_NO + 1) END ) AS TOTAL_COUNT
FROM TB_ECM_STOCK st LEFT OUTER JOIN TB_SMS_CUSTOMER cus ON cus.CUSTOMER_CODE = st.AGENT_CODE
WHERE st.ENT_CODE = #{srchEntCode}
AND st.REGISTER_DATE_TIME >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat})
AND st.REGISTER_DATE_TIME < DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))
AND st.TR_CODE = #{srchTrCode}
AND ISNULL((CASE WHEN st.TR_CODE IN('KOREX','KOREXMUL','HANJIN','LOTTE','JP-AIR','JP-SEA') THEN (CASE WHEN ISNULL(st.CURRENT_NO, 0) = 0 THEN CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.END_NO),1,11)) - CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.START_NO),1,11)) + 1 ELSE CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.END_NO),1,11)) - CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.CURRENT_NO),1,11)) END) WHEN st.TR_CODE IN('EMS-KP','EMS-TS') THEN (CASE WHEN ISNULL(st.CURRENT_NO, 0) = 0 THEN CONVERT(DECIMAL(9),SUBSTRING(CONVERT(VARCHAR(18),st.END_NO),1,8)) - CONVERT(DECIMAL(9),SUBSTRING(CONVERT(VARCHAR(18),st.START_NO),1,8)) + 1 ELSE CONVERT(DECIMAL(9),SUBSTRING(CONVERT(VARCHAR(18),st.END_NO),1,8)) - CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.CURRENT_NO),1,8)) END) ELSE (CASE WHEN ISNULL(st.CURRENT_NO, 0) = 0 THEN st.END_NO - st.START_NO + 1 ELSE st.END_NO - st.CURRENT_NO END) END ),0) > 0
AND ISNULL((CASE WHEN st.TR_CODE IN('KOREX','KOREXMUL','HANJIN','LOTTE','JP-AIR','JP-SEA') THEN (CASE WHEN ISNULL(st.CURRENT_NO, 0) = 0 THEN CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.END_NO),1,11)) - CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.START_NO),1,11)) + 1 ELSE CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.END_NO),1,11)) - CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.CURRENT_NO),1,11)) END) WHEN st.TR_CODE IN ('EMS-KP','EMS-TS') THEN (CASE WHEN ISNULL(st.CURRENT_NO, 0) = 0 THEN CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.END_NO),1,8)) - CONVERT(DECIMAL(9),SUBSTRING(CONVERT(VARCHAR(18),st.START_NO),1,8)) + 1 ELSE CONVERT(DECIMAL(9),SUBSTRING(CONVERT(VARCHAR(18),st.END_NO),1,8)) - CONVERT(DECIMAL(9),SUBSTRING(CONVERT(VARCHAR(18),st.CURRENT_NO),1,8)) END) ELSE (CASE WHEN ISNULL(st.CURRENT_NO, 0) = 0 THEN st.END_NO - st.START_NO + 1 ELSE st.END_NO - st.CURRENT_NO END) END ),0) = 0
AND st.AGENT_CODE = #{srchAgentCode}
AND st.START_NO = #{srchStockNo}
AND st.BOUND = #{srchBound}
AND st.BOUND_TYPE = #{srchBoundType}
AND st.STOCK_USE_YN = #{srchStockUseYn}

mapper.insert:
/* StockMapper.insertStock : Stock 데이터 등록 */
	
		 
				INSERT INTO TB_ECM_STOCK(
				
					TR_CODE
					, BOUND
					, BOUND_TYPE
					, AGENT_CODE
					, SEQ_NO
					, ENT_CODE
					, ENT_BUSINESS_CODE
					, STOCK_DATE
					, START_NO
					, END_NO
		 			, STOCK_TYPE
		 			, STOCK_METHOD
		 			, STOCK_USE_YN
					, REGISTER_USER_ID
					, REGISTER_DATE_TIME
					, UPDATE_USER_ID
					, UPDATE_DATE_TIME	
				
					)VALUES(
				
					#{trCode}
					, #{bound}
					, #{boundType}
					, #{agentCode}
					, (SELECT ISNULL(MAX(SEQ_NO),0) + 1 FROM TB_ECM_STOCK WHERE TR_CODE = #{trCode} AND BOUND = #{bound} AND BOUND_TYPE = #{boundType} AND AGENT_CODE = #{agentCode} )
					, #{entCode}
					, #{entBusinessCode}
					, #{registerDateTime}
					, #{startNo}
					, #{endNo}
					, '' 
					, '' 
					, #{stockUseYn}
					, #{inputUserId}
					, #{registerDateTime}
					, #{inputUserId}
					, GETDATE()
					
					)					 
		
		
				MERGE TB_ECM_STOCK AS A 
					USING (SELECT #{bound} AS BOUND, #{boundType} AS BOUND_TYPE, #{trCode} AS TR_CODE
								, #{startNo} AS START_NO, #{endNo} AS END_NO) AS B 
					ON (A.BOUND = B.BOUND AND A.BOUND_TYPE = B.BOUND_TYPE AND A.TR_CODE = B.TR_CODE
						AND A.START_NO = B.START_NO AND A.END_NO = B.END_NO)  
					WHEN NOT MATCHED BY TARGET THEN
					INSERT(
				
						TR_CODE
						, BOUND
						, BOUND_TYPE
						, AGENT_CODE
						, SEQ_NO
						, ENT_CODE
						, ENT_BUSINESS_CODE
						, STOCK_DATE
						, START_NO
						, END_NO
			 			, STOCK_TYPE
			 			, STOCK_METHOD
			 			, STOCK_USE_YN
						, REGISTER_USER_ID
						, REGISTER_DATE_TIME
						, UPDATE_USER_ID
						, UPDATE_DATE_TIME	
					
						)VALUES(
						
						#{trCode}
						, #{bound}
						, #{boundType}
						, #{entCode}
						, (SELECT ISNULL(MAX(SEQ_NO),0) + 1 FROM TB_ECM_STOCK WHERE TR_CODE = #{trCode} AND BOUND = #{bound} AND BOUND_TYPE = #{boundType})
						, #{entCode}
						, #{entBusinessCode}
						, #{registerDateTime}
						
						
						, #{startNo}
						, #{endNo}
						
						
							
							
							,CAST((CAST(CAST(SUBSTRING(CAST(#{endNo} AS VARCHAR),1,11) AS decimal)+1 AS VARCHAR) + CAST((CAST(SUBSTRING(CAST(#{endNo} AS VARCHAR),3,9) AS decimal)+1)% 7 AS VARCHAR)) AS decimal)
							
							
							,CAST((CAST(CAST(SUBSTRING(CAST(#{endNo} AS VARCHAR),1,11) AS decimal)+1 AS VARCHAR) + CAST((CAST(SUBSTRING(CAST(#{endNo} AS VARCHAR),1,11) AS decimal)+1)% 7 AS VARCHAR)) AS decimal)
							
							
							,CAST((CAST(CAST(SUBSTRING(CAST(#{endNo} AS VARCHAR),1,11) AS decimal)+1 AS VARCHAR) + CAST((CAST(SUBSTRING(CAST(#{endNo} AS VARCHAR),1,11) AS decimal)+1)% 7 AS VARCHAR)) AS decimal)
							
							
							, #{endNo}
							
							
							,CAST(#{endNo} AS decimal) + 1	
							
							
							, #{origEndNo} 
						
						
						, '' 
						, '' 
						, #{stockUseYn}
						, #{inputUserId}
						, #{registerDateTime}
						, #{inputUserId}
						, GETDATE()
						
						);

mapper.delete:
/* StockMapper.deleteStock : Stock Delete */
		DELETE FROM TB_ECM_STOCK
		WHERE ENT_CODE = #{entCode} 
		AND BOUND = #{bound} 
		AND BOUND_TYPE = #{boundType} 
		AND TR_CODE = #{trCode}
		AND AGENT_CODE = #{agentCode}
		AND SEQ_NO = #{seqNo}

mapper.select:
/* StockMapper.selectStockDetail : Stock Detail 화면 */ SELECT st.TR_CODE , st.BOUND , st.BOUND_TYPE , st.AGENT_CODE , st.SEQ_NO , st.ENT_CODE , st.ENT_BUSINESS_CODE , st.START_NO , st.END_NO , st.CURRENT_NO , st.STOCK_TYPE , st.STOCK_METHOD , st.STOCK_USE_YN , st.REGISTER_USER_ID , CONVERT(VARCHAR,st.REGISTER_DATE_TIME,23) AS REGISTER_DATE_TIME , st.UPDATE_USER_ID , CONVERT(VARCHAR,st.UPDATE_DATE_TIME,23) AS UPDATE_DATE_TIME , (CASE WHEN st.TR_CODE IN('KOREX','KOREXMUL','HANJIN') THEN (CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.END_NO),1,11)) - CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.START_NO),1,11)) + 1) WHEN st.TR_CODE IN('EMS-KP','EMS-TS') THEN (CONVERT(DECIMAL(9),SUBSTRING(CONVERT(VARCHAR(18),st.END_NO),1,8)) - CONVERT(DECIMAL(9),SUBSTRING(CONVERT(VARCHAR(18),st.START_NO),1,8)) + 1) ELSE (st.END_NO - st.START_NO + 1) END ) AS TOTAL_COUNT
FROM TB_ECM_STOCK st WHERE 1=1
AND st.ENT_CODE = #{entCode}
AND st.TR_CODE = #{srchTrCode}
AND st.BOUND = #{srchBound}
AND st.BOUND_TYPE = #{srchBoundType}
AND st.AGENT_CODE = #{srchAgentCode}
AND st.START_NO = #{srchStartNo}
AND st.END_NO = #{srchEndNo}
AND st.SEQ_NO = #{srchSeqNo}

/* StockMapper.selectVoidStockList : Stock List 조회 */

	SELECT TR_CODE
			, BOUND 
			, BOUND_TYPE
			, AGENT_CODE 
			, SEQ_NO 
			, VOID_STOCK_NO 
			, VOID_TYPE 
			, REGISTER_USER_ID 
			, REGISTER_DATE_TIME 
			, UPDATE_USER_ID 
			, UPDATE_DATE_TIME 
	FROM TB_ECM_STOCK_VOID tesv 
	WHERE 1=1
	
		AND tesv.TR_CODE = #{srchTrCode}
			
	
		AND tesv.BOUND = #{srchBound}
			
	
		AND tesv.BOUND_TYPE = #{srchBoundType}
	
	
		AND tesv.AGENT_CODE = #{srchAgentCode}
							
	
		
		AND tesv.VOID_STOCK_NO BETWEEN #{srchStartNo} AND #{srchEndNo}

mapper.update:
/* StockMapper.updateStockUseYn */
UPDATE TB_ECM_STOCK SET STOCK_USE_YN = #{stockUseYn}
WHERE

(
	TR_CODE = #{item.trCode}
	AND BOUND = #{item.bound}
	AND BOUND_TYPE = #{item.boundType}
	AND AGENT_CODE = #{item.agentCode}
	AND SEQ_NO = #{item.seqNo}
)

/* StockMapper.updateStock : xxxxxxx Stock 데이터 대리점에 부여 후 시작번호 업데이트   */
	UPDATE TB_ECM_STOCK
	SET 
	
		
			 START_NO = CAST((CAST(CAST(SUBSTRING(CAST(#{endNo} AS VARCHAR),1,11) AS decimal)+1 AS VARCHAR) + CAST((CAST(SUBSTRING(CAST(#{endNo} AS VARCHAR),3,9) AS decimal)+1)% 7 AS VARCHAR)) AS decimal)
		
		
			 START_NO = CAST((CAST(CAST(SUBSTRING(CAST(#{endNo} AS VARCHAR),1,11) AS decimal)+1 AS VARCHAR) + CAST((CAST(SUBSTRING(CAST(#{endNo} AS VARCHAR),1,11) AS decimal)+1)% 7 AS VARCHAR)) AS decimal)
		
		
			 START_NO = CAST(#{endNo} AS decimal) + 1	
		
	 
	WHERE BOUND = #{bound} AND BOUND_TYPE = #{boundType} AND TR_CODE = #{trCode}
	AND START_NO = #{origStartNo} AND END_NO = #{origEndNo}

mapper.insert:
	/* StockMapper.regrantStock : Stock 재부여 */
	
		BEGIN TRAN
		
		INSERT INTO TB_ECM_STOCK(
		
			TR_CODE
			, BOUND
			, BOUND_TYPE
			, AGENT_CODE
			, SEQ_NO
			, ENT_CODE
			, ENT_BUSINESS_CODE
			, STOCK_DATE
			, RE_STOCK_DATE
			, START_NO
			, END_NO
 			, STOCK_TYPE
 			, STOCK_METHOD
 			, STOCK_USE_YN
			, REGISTER_USER_ID
			, REGISTER_DATE_TIME
			, UPDATE_USER_ID
			, UPDATE_DATE_TIME	
		
			)VALUES(
		
			#{trCode}
			, #{bound}
			, #{boundType}
			, #{agentCode}
			, (SELECT ISNULL(MAX(SEQ_NO),0) + 1 FROM TB_ECM_STOCK WHERE TR_CODE = #{trCode} AND BOUND = #{bound} AND BOUND_TYPE = #{boundType} AND AGENT_CODE = #{agentCode} )
			, #{entCode}
			, #{entBusinessCode}
			, #{stockDate}
			, #{reStockDate}
			, #{startNo}
			, #{endNo}
			, '' 
			, '' 
			, #{stockUseYn}
			, #{inputUserId}
			, #{stockDate}
			, #{inputUserId}
			, GETDATE()
			
			)			
			
		UPDATE TB_ECM_STOCK
		SET 
		
			
				END_NO = CAST((CAST(CAST(SUBSTRING(CAST(#{startNo} AS VARCHAR),1,11) AS decimal)-1 AS VARCHAR) + CAST((CAST(SUBSTRING(CAST(#{startNo} AS VARCHAR),3,9) AS decimal)-1)% 7 AS VARCHAR)) AS decimal)
			
			
				END_NO = CAST((CAST(CAST(SUBSTRING(CAST(#{startNo} AS VARCHAR),1,11) AS decimal)-1 AS VARCHAR) + CAST((CAST(SUBSTRING(CAST(#{startNo} AS VARCHAR),1,11) AS decimal)-1)% 7 AS VARCHAR)) AS decimal)
			
			
				END_NO = CAST((CAST(CAST(SUBSTRING(CAST(#{startNo} AS VARCHAR),1,11) AS decimal)-1 AS VARCHAR) + CAST((CAST(SUBSTRING(CAST(#{startNo} AS VARCHAR),1,11) AS decimal)-1)% 7 AS VARCHAR)) AS decimal)
			
			
				END_NO = #{emsStockNo}
			
			
				 END_NO = CAST(#{startNo} AS decimal) - 1	
			
		 
		WHERE BOUND = #{bound} AND BOUND_TYPE = #{boundType} AND TR_CODE = #{trCode}
		
		AND SEQ_NO = #{seqNo}	
		AND AGENT_CODE = #{srchAgentCode}					 
		
		COMMIT TRAN

mapper.select:
		/* StockMapper.checkStockDuplication : Stock 중복체크 */

			SELECT COUNT(*)
			FROM TB_ECM_STOCK
			WHERE (START_NO BETWEEN #{startNo} AND #{endNo} OR END_NO BETWEEN #{startNo} AND #{endNo} )
			AND TR_CODE = #{trCode}
			AND BOUND = #{bound}
			AND BOUND_TYPE = #{boundType}
			AND ENT_CODE = #{entCode}

/* StockMapper.checkReStockDuplication : reStock 중복체크 */
SELECT
	(CASE WHEN st.TR_CODE IN('KOREX','KOREXMUL','HANJIN','LOTTE','JP-AIR','JP-SEA')
		THEN (CASE WHEN ISNULL(st.CURRENT_NO, 0) = 0 THEN CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.END_NO),1,11))
		- CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.START_NO),1,11)) + 1            
		ELSE CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.END_NO),1,11)) 
		- CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.CURRENT_NO),1,11)) END)
		WHEN st.TR_CODE IN ('EMS-KP','EMS-TS')
		THEN (CASE WHEN ISNULL(st.CURRENT_NO, 0) = 0 THEN CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.END_NO),1,8))
		- CONVERT(DECIMAL(9),SUBSTRING(CONVERT(VARCHAR(18),st.START_NO),1,8)) + 1            
		ELSE CONVERT(DECIMAL(9),SUBSTRING(CONVERT(VARCHAR(18),st.END_NO),1,8)) 
		- CONVERT(DECIMAL(9),SUBSTRING(CONVERT(VARCHAR(18),st.CURRENT_NO),1,8)) END)    
		ELSE (CASE WHEN ISNULL(st.CURRENT_NO, 0) = 0 THEN st.END_NO - st.START_NO + 1          
		ELSE st.END_NO - st.CURRENT_NO END) END        ) AS UNUSED_COUNT 
FROM TB_ECM_STOCK st
WHERE st.ENT_CODE = #{entCode}
AND st.BOUND = #{bound}
AND st.BOUND_TYPE = #{boundType}
AND st.TR_CODE = #{trCode}
AND st.AGENT_CODE = #{srchAgentCode}
AND st.SEQ_NO = #{seqNo}

/* StockMapper.selectStockListV2 : Stock List 조회 */
SELECT st.ENT_CODE , st.TR_CODE , (SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = st.ENT_CODE AND CODE = st.TR_CODE AND GROUP_CODE = 'ECM_DELIVERY_CODE') AS TR_NAME , st.BOUND , st.BOUND_TYPE , MIN(st.STOCK_DATE) AS STOCK_DATE , MIN(st.START_NO) AS START_NO , MAX(st.END_NO) AS END_NO , SUM(CASE WHEN st.TR_CODE IN('KOREX','KOREXMUL','HANJIN','JP-AIR','JP-SEA','LOTTE') THEN (CASE WHEN ISNULL(st.CURRENT_NO, 0) = 0 THEN 0 ELSE CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.CURRENT_NO),1,11)) - CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.START_NO),1,11)) + 1 END) WHEN st.TR_CODE IN ('EMS-KP','EMS-TS') THEN (CASE WHEN ISNULL(st.CURRENT_NO, 0) = 0 THEN 0 ELSE CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.CURRENT_NO),1,8)) - CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.START_NO),1,8)) + 1 END) ELSE (CASE WHEN ISNULL(st.CURRENT_NO, 0) = 0 THEN 0 ELSE st.CURRENT_NO - st.START_NO + 1 END) END ) AS USED_COUNT , SUM(CASE WHEN st.TR_CODE IN('KOREX','KOREXMUL','HANJIN','JP-AIR','JP-SEA','LOTTE') THEN (CASE WHEN ISNULL(st.CURRENT_NO, 0) = 0 THEN CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.END_NO),1,11)) - CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.START_NO),1,11)) + 1 ELSE CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.END_NO),1,11)) - CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.CURRENT_NO),1,11)) END) WHEN st.TR_CODE IN ('EMS-KP','EMS-TS') THEN (CASE WHEN ISNULL(st.CURRENT_NO, 0) = 0 THEN CONVERT(DECIMAL(9),SUBSTRING(CONVERT(VARCHAR(18),st.END_NO),1,8)) - CONVERT(DECIMAL(9),SUBSTRING(CONVERT(VARCHAR(18),st.START_NO),1,8)) + 1 ELSE CONVERT(DECIMAL(9),SUBSTRING(CONVERT(VARCHAR(18),st.END_NO),1,8)) - CONVERT(DECIMAL(9),SUBSTRING(CONVERT(VARCHAR(18),st.CURRENT_NO),1,8)) END) ELSE (CASE WHEN ISNULL(st.CURRENT_NO, 0) = 0 THEN st.END_NO - st.START_NO + 1 ELSE st.END_NO - st.CURRENT_NO END) END ) AS UNUSED_COUNT , SUM(CASE WHEN st.TR_CODE IN('KOREX','KOREXMUL','HANJIN','JP-AIR','JP-SEA','LOTTE') THEN (CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.END_NO),1,11)) - CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.START_NO),1,11)) + 1) WHEN st.TR_CODE IN ('EMS-KP', 'EMS-TS') THEN (CONVERT(DECIMAL(9),SUBSTRING(CONVERT(VARCHAR(18),st.END_NO),1,8)) - CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.START_NO),1,8)) + 1) ELSE (st.END_NO - st.START_NO + 1) END ) AS TOTAL_COUNT , MIN(st.REGISTER_DATE_TIME) AS REGISTER_DATE_TIME , MAX(st.REGISTER_USER_ID) AS REGISTER_USER_ID , COUNT(*) AS SPLIT_COUNT FROM TB_ECM_STOCK st
WHERE st.ENT_CODE = #{srchEntCode}
AND st.REGISTER_DATE_TIME >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat})
AND st.REGISTER_DATE_TIME < DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))
AND st.TR_CODE = #{srchTrCode}
AND ISNULL((CASE WHEN st.TR_CODE IN('KOREX','KOREXMUL','HANJIN','LOTTE','JP-AIR','JP-SEA') THEN (CASE WHEN ISNULL(st.CURRENT_NO, 0) = 0 THEN CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.END_NO),1,11)) - CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.START_NO),1,11)) + 1 ELSE CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.END_NO),1,11)) - CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.CURRENT_NO),1,11)) END) WHEN st.TR_CODE IN('EMS-KP','EMS-TS') THEN (CASE WHEN ISNULL(st.CURRENT_NO, 0) = 0 THEN CONVERT(DECIMAL(9),SUBSTRING(CONVERT(VARCHAR(18),st.END_NO),1,8)) - CONVERT(DECIMAL(9),SUBSTRING(CONVERT(VARCHAR(18),st.START_NO),1,8)) + 1 ELSE CONVERT(DECIMAL(9),SUBSTRING(CONVERT(VARCHAR(18),st.END_NO),1,8)) - CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.CURRENT_NO),1,8)) END) ELSE (CASE WHEN ISNULL(st.CURRENT_NO, 0) = 0 THEN st.END_NO - st.START_NO + 1 ELSE st.END_NO - st.CURRENT_NO END) END ),0) > 0
AND ISNULL((CASE WHEN st.TR_CODE IN('KOREX','KOREXMUL','HANJIN','LOTTE','JP-AIR','JP-SEA') THEN (CASE WHEN ISNULL(st.CURRENT_NO, 0) = 0 THEN CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.END_NO),1,11)) - CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.START_NO),1,11)) + 1 ELSE CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.END_NO),1,11)) - CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.CURRENT_NO),1,11)) END) WHEN st.TR_CODE IN ('EMS-KP','EMS-TS') THEN (CASE WHEN ISNULL(st.CURRENT_NO, 0) = 0 THEN CONVERT(DECIMAL(12),SUBSTRING(CONVERT(VARCHAR(18),st.END_NO),1,8)) - CONVERT(DECIMAL(9),SUBSTRING(CONVERT(VARCHAR(18),st.START_NO),1,8)) + 1 ELSE CONVERT(DECIMAL(9),SUBSTRING(CONVERT(VARCHAR(18),st.END_NO),1,8)) - CONVERT(DECIMAL(9),SUBSTRING(CONVERT(VARCHAR(18),st.CURRENT_NO),1,8)) END) ELSE (CASE WHEN ISNULL(st.CURRENT_NO, 0) = 0 THEN st.END_NO - st.START_NO + 1 ELSE st.END_NO - st.CURRENT_NO END) END ),0) = 0
AND st.AGENT_CODE = #{srchAgentCode}
AND st.START_NO = #{srchStockNo}
AND st.BOUND = #{srchBound}
AND st.BOUND_TYPE = #{srchBoundType}
AND st.STOCK_USE_YN = #{srchStockUseYn}
GROUP BY st.ENT_CODE, st.TR_CODE, st.BOUND, st.BOUND_TYPE
